 addresses=[0,4095,4096,8191,12288,0];pages=[a//4096 for a in addresses];assert pages==[0,0,1,1,3,0];grouped=[0,0,0,1,1,1,3,3,3];interleaved=[0,1,3]*3;windows=lambda p:[sorted(set(p[i:i+3])) for i in range(0,len(p),3)];assert len(grouped)==len(interleaved) and set(grouped)==set(interleaved) and windows(grouped)!=windows(interleaved);records['working-sets']={'pages':pages,'unique':sorted(set(pages)),'grouped_windows':windows(grouped),'interleaved_windows':windows(interleaved),'requested_bytes_each':9,'RSS_from_page_ids':None,'physical_IO_from_fault_count':None}
