 quota,period=20000,100000;aligned=5*quota;segments=[(50000,100000)]+[(i*period,(i+1)*period) for i in range(1,5)]+[(500000,550000)];sliding=sum(min(quota,b-a) for a,b in segments);assert aligned==100000 and sliding==120000;records['quota-boundary']={'quota':quota,'period':period,'five_aligned_periods':aligned,'five_period_duration_midperiod':sliding,'assumptions':['single struct lr_cpu model','no burst','independent period budgets','always runnable','no tighter parent','no carry beyond declared period'],'latency_guarantee':None,'core_ownership':False,'tighter_parent_ceiling':5*10000}
